#!/usr/bin/env python3
# Some portions generated by Codex. Independent matched forks; no cross-workload pooled claim.
import pathlib,json,statistics,math
p=pathlib.Path(__file__).resolve().parent;result={};metrics=['headersMs','firstRowMs','batchMs','endMs','eofMs']
for shape in ['small6','reference6','wide30','large6']:
 fs=[]
 for d in sorted((p/'runs').glob('matched-'+shape+'-*')):
  m=json.loads((d/'manifest.json').read_text())
  if m.get('status')!='passed':continue
  rows=[json.loads((d/f'query-{i}.json').read_text()) for i in range(20)]
  assert all(x['rows']==m['expectedRows'] for x in rows)
  counters={k:[x['after'][k]-x['before'][k] for x in rows] for k in rows[0]['after'] if ':' in k and isinstance(rows[0]['after'][k],int) and k!='ledger:peakUsedBytes'}
  fs.append({'name':d.name,'arm':m['arm'],'means':{k:statistics.mean(x[k] for x in rows) for k in metrics},'eofByIndex':[x['eofMs'] for x in rows],'firstRowByIndex':[x['firstRowMs'] for x in rows],'counterDeltas':counters,'ledgerPeakMax':max(x['after']['ledger:peakUsedBytes'] for x in rows),'expectedRows':m['expectedRows']})
 if len(fs)!=8:result[shape]={'status':'incomplete','finishedForks':len(fs)};continue
 arms={}
 for arm in ['base','stack']:
  ff=[f for f in fs if f['arm']==arm];ix=[statistics.mean(f['eofByIndex'][i] for f in ff) for i in range(20)];arms[arm]={'means':{k:statistics.mean(f['means'][k] for f in ff) for k in metrics},'eofIndexMeans':ix,'eofSegments':[statistics.mean(ix[:7]),statistics.mean(ix[7:13]),statistics.mean(ix[13:])],'forkRangeEofMs':[min(f['means']['eofMs'] for f in ff),max(f['means']['eofMs'] for f in ff)]}
 blocks=[{f['arm']:f['means'] for f in fs[i:i+2]} for i in range(0,8,2)];contrasts={}
 for k in metrics:
  xs=[math.log(b['stack'][k]/b['base'][k]) for b in blocks];m=statistics.mean(xs);e=3.1824463*statistics.stdev(xs)/2;a,b=arms['base']['means'][k],arms['stack']['means'][k]
  contrasts[k]={'latencyReductionPercent':100*(1-b/a),'derivedThroughputChangePercent':100*(a/b-1),'pairedReductionPercent':[100*(1-math.exp(x)) for x in xs],'descriptive95ReductionInterval':[100*(1-math.exp(m+e)),100*(1-math.exp(m-e))]}
 result[shape]={'status':'complete','arms':arms,'contrasts':contrasts,'forks':fs}
print(json.dumps(result,indent=2))
